@Test
    void testCreate_notEnoughBytes_1_oe() {
        // arrange
        final byte[] bytes = new byte[1];
        final ByteArrayInputStream in = new ByteArrayInputStream(bytes);

        // act/assert
        GeometryTestUtils.assertThrowsWithMessage( () -> StlFacetDefinitionReaders.create(in, null), IllegalStateException.class, "Cannot determine STL format: attempted to read 5 bytes but found only 1 available");
    }

@Test
    void testReadFacet_failOnNonPolygon_1_oe() {
        // arrange
        final ObjFacetDefinitionReader reader = reader(
                "o test\n\n" +
                "v 0 0 0\r\n" +
                "v 1 0 0\n" +
                "v 1 1 0\r" +
                "v 0 1 0\n" +
                "vn 0 0 1\n" +
                "f 1//1 2//1 3//1\n" +
                "curv non-polygon data\n");

        reader.setFailOnNonPolygonKeywords(true);

        // act/assert
        GeometryTestUtils.assertThrowsWithMessage( () -> EuclideanIOTestUtils.readAll(reader), IllegalStateException.class, Pattern.compile("^Parsing failed.*"));
    }

@Test
    void testWriteFace_invalidVertexNumber_1_oe() {
        // arrange
        final StringWriter writer = new StringWriter();

        // act
        GeometryTestUtils.assertThrowsWithMessage(() -> { try (ObjWriter objWriter = new ObjWriter(writer)) { objWriter.writeFace(1, 2); } }, IllegalArgumentException.class, "Face must have more than 3 vertices; found 2");
    }

@Test
    void testWriteFace_vertexIndexOutOfBounds_1_oe() {
        // arrange
        final StringWriter writer = new StringWriter();

        // act/assert
        GeometryTestUtils.assertThrowsWithMessage(() -> { try (ObjWriter objWriter = new ObjWriter(writer)) { objWriter.writeVertex(Vector3D.ZERO); objWriter.writeVertex(Vector3D.of(1, 1, 1)); objWriter.writeFace(0, 1, 2); } }, IndexOutOfBoundsException.class, "Vertex index out of bounds: 2");
    }

